head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) {
    return createElementNS(XHTML_NS, tagName, options);
  };
})();
